+import type { OrderItem } from "../types.js";
+
+export interface SubtotalCalculationResult {
+  subtotalCents: number;
+  itemCount: number;
+}
+
+export interface PricingStrategy {
+  calculateSubtotal(items: OrderItem[]): SubtotalCalculationResult;
+}
+
+export class StandardPricingStrategy implements PricingStrategy {
+  validateItem(item: OrderItem): void {
+    if (item.quantity <= 0 || item.unitPriceCents < 0) {
+      throw new Error(`Invalid item quantity or price for item ${item.id}`);
+    }
+  }
+
+  calculateSubtotal(items: OrderItem[]): SubtotalCalculationResult {
+    let subtotalCents = 0;
+    let itemCount = 0;
+
+    for (const item of items) {
+      this.validateItem(item);
+      subtotalCents += item.unitPriceCents * item.quantity;
+      itemCount += item.quantity;
+    }
+
+    return { subtotalCents, itemCount };
+  }
+}
+
+export class PricingCalculator {
+  constructor(
+    private strategy: PricingStrategy = new StandardPricingStrategy()
+  ) {}
+
+  calculate(items: OrderItem[]): SubtotalCalculationResult {
+    return this.strategy.calculateSubtotal(items);
+  }
+}
