+import type { OrderItem } from "../types.js";
+
+export interface TaxStrategy {
+  calculateTax(items: OrderItem[], discountRatio: number): number;
+}
+
+export class CategoryTaxStrategy implements TaxStrategy {
+  getTaxRate(category: OrderItem["category"]): number {
+    switch (category) {
+      case "food":
+        return 0;
+      case "clothing":
+        return 0.05;
+      case "electronics":
+        return 0.15;
+      case "general":
+      default:
+        return 0.10;
+    }
+  }
+
+  calculateTax(items: OrderItem[], discountRatio: number): number {
+    let taxCents = 0;
+    for (const item of items) {
+      const itemSubtotal = item.unitPriceCents * item.quantity * discountRatio;
+      const rate = this.getTaxRate(item.category);
+      taxCents += Math.round(itemSubtotal * rate);
+    }
+    return taxCents;
+  }
+}
+
+export class TaxCalculator {
+  constructor(
+    private strategy: TaxStrategy = new CategoryTaxStrategy()
+  ) {}
+
+  calculate(items: OrderItem[], discountRatio: number): number {
+    return this.strategy.calculateTax(items, discountRatio);
+  }
+}
